package com.shopsphere.security;import com.shopsphere.repository.UserRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;@Component public class JwtAuthFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserRepository users;public JwtAuthFilter(JwtService j,UserRepository u){jwt=j;users=u;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&jwt.valid(h.substring(7))){try{users.findByEmail(jwt.email(h.substring(7))).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())))));}catch(Exception ignored){}}c.doFilter(r,s);}}